commands.command:
printf '%s
' '--repo-files--'; find /etc/yum.repos.d /etc/yum/repos.d /etc/distro.repos.d -maxdepth 1 -type f -print -exec sed -n '1,220p' {} \; 2>/dev/null; printf '%s
' '--network--'; getent hosts mirror.stream.centos.org || true; curl -I -L --max-time 15 -sS -o /dev/null -w 'centos_http=%{http_code} remote=%{remote_ip}
' https://mirror.stream.centos.org/10-stream/BaseOS/x86_64/os/Packages/; curl -I -L --max-time 15 -sS -o /dev/null -w 'ubi_http=%{http_code} remote=%{remote_ip}
' https://cdn-ubi.redhat.com/content/public/ubi/dist/ubi10/10/x86_64/baseos/os/

tee /etc/rsyslog.d/10-local0-tls-server.conf >/dev/null <<'ANTRIEB_MTLS_EOF'
global(
    DefaultNetstreamDriver="gtls"
    DefaultNetstreamDriverCAFile="/etc/pki/rsyslog/ca.crt"
    DefaultNetstreamDriverCertFile="/etc/pki/rsyslog/node4.crt"
    DefaultNetstreamDriverKeyFile="/etc/pki/rsyslog/node4.key"
)

module(
    load="imtcp"
    StreamDriver.Name="gtls"
    StreamDriver.Mode="1"
    StreamDriver.AuthMode="x509/name"
    PermittedPeer=["node1","node2","node3"]
)

ruleset(name="tls_local0") {
    if ($syslogfacility-text == "local0" and $fromhost-ip == "10.100.218.10") then {
        action(type="omfile" file="/var/log/rsyslog-apps/node1.log" createDirs="on" dirCreateMode="0750" fileCreateMode="0640")
        stop
    }
    if ($syslogfacility-text == "local0" and $fromhost-ip == "10.100.218.11") then {
        action(type="omfile" file="/var/log/rsyslog-apps/node2.log" createDirs="on" dirCreateMode="0750" fileCreateMode="0640")
        stop
    }
    if ($syslogfacility-text == "local0" and $fromhost-ip == "10.100.218.12") then {
        action(type="omfile" file="/var/log/rsyslog-apps/node3.log" createDirs="on" dirCreateMode="0750" fileCreateMode="0640")
        stop
    }
    stop
}

input(type="imtcp" address="10.100.218.13" port="6514" ruleset="tls_local0")
ANTRIEB_MTLS_EOF
chmod 644 /etc/rsyslog.d/10-local0-tls-server.conf
